def test_content_returns_bibtex_and_ris_as_text(client, httpx_mock):
    bib = load_fixture("cn_crossref_bibtex.bib")
    httpx_mock.add_response(text=bib)
    text = client.content("10.1038/nature12373", BIBTEX)
    assert isinstance(text, str)
    assert text.strip().startswith("@article")
    ris = load_fixture("cn_crossref_ris.txt")
    httpx_mock.add_response(text=ris)
    assert (client.content("10.1038/nature12373", RIS)).startswith("TY  - JOUR")
    requests = httpx_mock.get_requests()
    assert requests[0].headers["accept"] == BIBTEX
    assert requests[1].headers["accept"] == RIS


@pytest.mark.parametrize(
    ("fixture", "doi", "media_type", "start"),
    [
        ("cn_medra_bibtex.bib", "10.1400/56174", BIBTEX, "@article"),
        ("cn_datacite_bibtex.bib", "10.5281/zenodo.1238808", BIBTEX, "@misc"),
        ("cn_datacite_ris.txt", "10.5281/zenodo.1238808", RIS, "TY  - COMP"),
        ("cn_crossref_unixref.xml", "10.1038/nature12373", UNIXREF_XML, "<?xml"),
    ],
)
def test_content_returns_the_text_of_every_agency(
    client, httpx_mock, fixture, doi, media_type, start
):
    body = load_fixture(fixture)
    httpx_mock.add_response(text=body)
    assert (client.content(doi, media_type)).strip().startswith(start)
    assert last_request(httpx_mock).headers["accept"] == media_type


def test_content_follows_redirects(client, httpx_mock):
    """The client asks the framework to follow the resolver's 302."""
    httpx_mock.add_response(
        status_code=302,
        headers={"Location": "https://api.crossref.org/v1/works/x/transform"},
        text=load_fixture("redirect_crossref.html"),
    )
    httpx_mock.add_response(json=CSL)
    item = client.content("10.1038/nature12373", CSL_JSON)
    assert isinstance(item, CslItem)
    assert len(httpx_mock.get_requests()) == 2


def test_content_of_no_metadata_is_none(client, httpx_mock):
    """204 means the DOI exists but the agency has no metadata for it."""
    httpx_mock.add_response(status_code=204)
    httpx_mock.add_response(status_code=204)
    assert client.content("10.1038/nature12373", CSL_JSON) is None
    assert client.content("10.1038/nature12373", BIBTEX) is None


def test_content_rejects_empty_media_type(client, httpx_mock):
    with pytest.raises(ConfigurationError, match="non-empty"):
        client.content("10.1038/nature12373", "  ")
    assert not httpx_mock.get_requests()


def test_content_rejects_a_malformed_doi_before_sending(client, httpx_mock):
    with pytest.raises(ConfigurationError, match="Not a DOI name"):
        client.content("nonsense", CSL_JSON)
    assert not httpx_mock.get_requests()


def test_content_percent_encodes_the_doi(client, httpx_mock):
    httpx_mock.add_response(text="@article{x}")
    client.content("https://doi.org/10.1000/res%23test", BIBTEX)
    assert last_request(httpx_mock).url.raw_path == b"/10.1000/res%23test"


